"""League table formats — HU and multi-way ring sizes (Phase 9)."""from __future__ import annotationsfrom dataclasses import dataclass@dataclass(frozen=True, slots=True)class TableFormat:    """One scheduled table shape."""    format_id: str    num_seats: int    label: str    @property    def is_hu(self) -> bool:        return self.num_seats == 2    @property    def is_multiway_table(self) -> bool:        return self.num_seats >= 3DEFAULT_FORMATS: tuple[TableFormat, ...] = (    TableFormat("hu", 2, "Heads-up"),    TableFormat("6max", 6, "6-max ring"),    TableFormat("9max", 9, "9-max ring"),)def parse_table_sizes(spec: str) -> tuple[int, ...]:    """Parse ``2,6,9`` or ``hu,6max`` into seat counts."""    aliases = {"hu": 2, "6max": 6, "9max": 9, "10max": 10}    out: list[int] = []    for part in spec.replace(" ", "").split(","):        if not part:            continue        low = part.lower()        if low in aliases:            out.append(aliases[low])        else:            n = int(part)            if not (2 <= n <= 10):                msg = f"table size out of range: {n}"                raise ValueError(msg)            out.append(n)    if not out:        return tuple(f.num_seats for f in DEFAULT_FORMATS)    return tuple(dict.fromkeys(out))def formats_from_seats(sizes: tuple[int, ...]) -> tuple[TableFormat, ...]:    labels = {2: "hu", 6: "6max", 9: "9max", 10: "10max"}    fmts: list[TableFormat] = []    for n in sizes:        fid = labels.get(n, f"{n}max")        fmts.append(TableFormat(fid, n, f"{n}-max" if n > 2 else "Heads-up"))    return tuple(fmts)